namespace ghidra.graph.viewer.layout;





using edu.uci.ics.jung.algorithms.layout;
using generic.theme;
using ghidra.graph;
using ghidra.graph.graphs;
using ghidra.graph.viewer;
using ghidra.graph.viewer;
using ghidra.util.exception;
using ghidra.util.task;

/**
 * A layout provider that works on {@link JungDirectedVisualGraph}s.  This class allows the 
 * Jung layouts to be used where {@link VisualGraph}s are used.
 *
 * @param <V> the vertex type
 * @param <E> the edge type
 * @param <G> the graph type
 */
//@formatter:off
public abstract class JungLayoutProvider<V, E, G> : AbstractLayoutProvider<V, E, G> where V : VisualVertex where E : VisualEdge<V> where G : JungDirectedVisualGraph<V, E> {
//@formatter:on

	private static readonly Icon DEFAULT_ICON = new GIcon("icon.graph.layout.default");

	protected abstract Layout<V, E> createLayout(G g);

	/* @Override */
	public VisualGraphLayout<V, E> getLayout(G g, TaskMonitor monitor)
    {

		Objects.requireNonNull(g);

		Layout<V, E> jungLayout = createLayout(g);

		initVertexLocations(g, jungLayout);

		return new(jungLayout);
	}

	// Note: each provider really should load its own icon so that the toolbar item can 
	//       signal to the user which layout is active
	/* @Override */
	public Icon getActionIcon() {
		return DEFAULT_ICON;
	}
}
